    /// CR 707.10 + CR 608.2c: a spell copy put onto the stack can be an
    /// anaphoric referent only when the parent resolution produced exactly one
    /// copied stack object.
    #[test]
    fn stack_pushed_parent_referent_requires_singular_copy() {
        let mut state = GameState::new_two_player(42);
        let first = create_object(
            &mut state,
            CardId(1),
            PlayerId(0),
            "First Copy".to_string(),
            Zone::Stack,
        );
        let second = create_object(
            &mut state,
            CardId(2),
            PlayerId(0),
            "Second Copy".to_string(),
            Zone::Stack,
        );
        let single = [GameEvent::StackPushed { object_id: first }];
        let multiple = [
            GameEvent::StackPushed { object_id: first },
            GameEvent::StackPushed { object_id: second },
        ];

        assert_eq!(
            parent_referent_context_from_events(&state, &single).map(|snapshot| snapshot.object_id),
            Some(first),
            "one copied spell can feed ParentTarget"
        );
        assert!(
            parent_referent_context_from_events(&state, &multiple).is_none(),
            "multiple copied spells must not bind ParentTarget arbitrarily"
        );
    }

    /// Build a bare `ZoneChanged` event carrying `mana_value` on its record, so
    /// a bound referent's LKI payload can be asserted (not merely its presence).
    fn zone_change_event(object_id: ObjectId, from: Zone, to: Zone, mana_value: u32) -> GameEvent {
        GameEvent::ZoneChanged {
            object_id,
            from: Some(from),
            to,
            record: Box::new(ZoneChangeRecord {
                mana_value,
                ..ZoneChangeRecord::test_minimal(object_id, Some(from), to)
            }),
        }
    }

    /// CR 608.2h: a draw (Library -> Hand) moves an object from a HIDDEN zone,
    /// not "from a public zone to a hidden zone", so it establishes no last
    /// known information and must never bind an anaphoric referent. Without this
    /// exclusion every draw in the game would bind one.
    #[test]
    fn library_to_hand_move_establishes_no_parent_referent() {
        let state = GameState::new_two_player(42);
        let events = [zone_change_event(ObjectId(1), Zone::Library, Zone::Hand, 3)];
        assert!(
            parent_referent_context_from_events(&state, &events).is_none(),
            "a draw has a hidden source zone and must not bind a referent"
        );
    }

    /// CR 608.2h: moving an object "from a public zone to a hidden zone" leaves
    /// last known information a later instruction can refer to — Volcanic
    /// Vision's "that card's mana value" after a Graveyard -> Hand return.
    #[test]
    fn graveyard_to_hand_move_binds_referent_with_move_time_mana_value() {
        let state = GameState::new_two_player(42);
        let events = [zone_change_event(
            ObjectId(1),
            Zone::Graveyard,
            Zone::Hand,
            3,
        )];
        let referent = parent_referent_context_from_events(&state, &events)
            .expect("a public -> hidden move leaves last known information");
        assert_eq!(referent.object_id, ObjectId(1));
        assert_eq!(
            referent.lki.mana_value, 3,
            "the referent must carry the move-time mana value"
        );
    }

    /// CR 608.2k: the singular guard still applies across the widened predicate —
    /// a public -> Hand return plus a second qualifying move in the same span has
    /// no single resolvable "that card".
    #[test]
    fn multiple_qualifying_moves_bind_no_parent_referent() {
        let state = GameState::new_two_player(42);
        let events = [
            zone_change_event(ObjectId(1), Zone::Graveyard, Zone::Hand, 3),
            zone_change_event(ObjectId(2), Zone::Battlefield, Zone::Graveyard, 5),
        ];
        assert!(
            parent_referent_context_from_events(&state, &events).is_none(),
            "two qualifying moves have no singular anaphoric referent"
        );
    }

    /// CR 608.2c: duplicate events for the same tapped creature still describe
    /// one singular referent.
    #[test]
    fn duplicate_tap_events_for_same_creature_still_capture_single_referent() {
        let mut state = GameState::new_two_player(42);
        let creature = create_object(
            &mut state,
            CardId(1),
            PlayerId(0),
            "Tapped".to_string(),
            Zone::Battlefield,
        );
        {
            let obj = state.objects.get_mut(&creature).unwrap();
            obj.card_types.core_types.push(CoreType::Creature);
            obj.base_power = Some(4);
            obj.base_toughness = Some(4);
            obj.power = Some(4);
            obj.toughness = Some(4);
        }
        let events = vec![
            GameEvent::PermanentTapped {
                object_id: creature,
                caused_by: None,
                incarnation: None,
            },
            GameEvent::PermanentTapped {
                object_id: creature,
                caused_by: None,
                incarnation: None,
            },
        ];
        let referent = parent_referent_context_from_events(&state, &events)
            .expect("duplicate tap events for one creature still have a singular referent");
        assert_eq!(referent.object_id, creature);
        assert_eq!(referent.lki.power, Some(4));
    }

    #[test]
    fn is_known_effect_rejects_unimplemented() {
        let known = Effect::DealDamage {
            amount: QuantityExpr::Fixed { value: 1 },
            target: TargetFilter::Any,
            damage_source: None,
            excess: None,
        };
        assert!(is_known_effect(&known));

        let unknown = Effect::Unimplemented {
            name: "Fateseal".to_string(),
            description: None,
        };
        assert!(!is_known_effect(&unknown));

        // RuntimeHandled is a known effect — it's handled by a dedicated engine path
        let runtime = Effect::RuntimeHandled {
            handler: crate::types::ability::RuntimeHandler::NinjutsuFamily,
        };
        assert!(is_known_effect(&runtime));
    }

    /// CR 508.6: "each player this creature attacked this turn" must bind to
    /// the source creature's own attacked-defender ledger, not the controller's
    /// aggregate "you attacked" set.
    #[test]
    fn source_attacked_this_turn_player_filter_is_per_creature() {
        let mut state = GameState::new(FormatConfig::free_for_all(), 3, 42);
        let angel = create_object(
            &mut state,
            CardId(100),
            PlayerId(0),
            "Angel of Destiny".to_string(),
            Zone::Battlefield,
        );
        let other_attacker = create_object(
            &mut state,
            CardId(101),
            PlayerId(0),
            "Other Attacker".to_string(),
            Zone::Battlefield,
        );

        state
            .attacked_defenders_this_turn
            .entry(PlayerId(0))
            .or_default()
            .extend([PlayerId(1), PlayerId(2)]);
        state
            .creature_attacked_defenders_this_turn
            .entry(angel)
            .or_default()
            .insert(PlayerId(1));
        state
            .creature_attacked_defenders_this_turn
            .entry(other_attacker)
            .or_default()
            .insert(PlayerId(2));

        assert!(
            matches_player_scope(
                &state,
                PlayerId(2),
                &PlayerFilter::OpponentAttacked {
                    subject: AttackSubject::You,
                    scope: CombatHistoryScope::ThisTurn,
                },
                PlayerId(0),
                angel,
            ),
            "the controller aggregate should include every player any creature attacked",
        );
        assert!(
            !matches_player_scope(
                &state,
                PlayerId(2),
                &PlayerFilter::OpponentAttacked {
                    subject: AttackSubject::Source,
                    scope: CombatHistoryScope::ThisTurn,
                },
                PlayerId(0),
                angel,
            ),
            "Angel must not affect a player attacked only by a different creature",
        );
        assert!(
            matches_player_scope(
                &state,
                PlayerId(1),
                &PlayerFilter::OpponentAttacked {
                    subject: AttackSubject::Source,
                    scope: CombatHistoryScope::ThisTurn,
                },
                PlayerId(0),
                angel,
            ),
            "Angel must still affect the player it attacked",
        );
    }

    #[test]
    fn player_attribute_threshold_binds_starting_life_to_candidate() {
        let mut format = crate::types::format::FormatConfig::archenemy();
        format.archenemy_player = Some(PlayerId(1));
        let mut state = GameState::new(format, 3, 42);
        state
            .players
            .iter_mut()
            .find(|p| p.id == PlayerId(1))
            .unwrap()
            .life = 15;
        let half_starting_life = QuantityExpr::DivideRounded {
            inner: Box::new(QuantityExpr::Ref {
                qty: QuantityRef::StartingLifeTotal {
                    player: PlayerScope::ScopedPlayer,
                },
            }),
            divisor: 2,
            rounding: RoundingMode::Down,
        };
        let predicate = PlayerFilter::PlayerAttribute {
            relation: PlayerRelation::Opponent,
            attr: Box::new(QuantityRef::LifeTotal {
                player: PlayerScope::ScopedPlayer,
            }),
            comparator: Comparator::LT,
            value: Box::new(half_starting_life),
        };
        let controller = PlayerId(0);
        let source = ObjectId(900);

        assert!(matches_player_scope(
            &state,
            PlayerId(1),
            &predicate,
            controller,
            source,
        ));
        // Strict boundary: 20 is not less than half of the candidate's 40.
        state
            .players
            .iter_mut()
            .find(|p| p.id == PlayerId(1))
            .unwrap()
            .life = 20;
        assert!(!matches_player_scope(
            &state,
            PlayerId(1),
            &predicate,
            controller,
            source,
        ));

        // Ordinary baseline sanity: in free-for-all the candidate starts at
        // 20, so life 11 is below half (10? No: preserve integer rounding; 11
        // is above). Life 9 is the qualifying control value.
        let mut ordinary = GameState::new_two_player(43);
        ordinary
            .players
            .iter_mut()
            .find(|p| p.id == PlayerId(1))
            .unwrap()
            .life = 11;
        assert!(!matches_player_scope(
            &ordinary,
            PlayerId(1),
            &predicate,
            controller,
            source,
        ));
        ordinary
            .players
            .iter_mut()
            .find(|p| p.id == PlayerId(1))
            .unwrap()
            .life = 9;
        assert!(matches_player_scope(
            &ordinary,
            PlayerId(1),
            &predicate,
            controller,
            source,
        ));
    }

