    /// Telemetry `game_summary` surface: resolving an `Effect::Unimplemented`
    /// records the source card's oracle id in `unimplemented_oracle_ids`
    /// (name fallback for tokens/emblems with no `printed_ref`), and dedups on
    /// repeated resolution. Diagnostics plumbing only — no rules behavior.
    #[test]
    fn unimplemented_effect_records_source_in_game_summary() {
        let mut state = GameState::new_two_player(42);

        // Card object with a printed oracle id.
        let mut card = crate::game::game_object::GameObject::new(
            ObjectId(7),
            CardId(700),
            PlayerId(0),
            "Fancy Card".to_string(),
            Zone::Stack,
        );
        card.printed_ref = Some(crate::types::card::PrintedCardRef {
            oracle_id: "oracle-abc-123".to_string(),
            face_name: "Fancy Card".to_string(),
        });
        state.objects.insert(ObjectId(7), card);

        // Token object with no printed_ref — must fall back to the name.
        let token = crate::game::game_object::GameObject::new(
            ObjectId(8),
            CardId(0),
            PlayerId(0),
            "Goblin Token".to_string(),
            Zone::Battlefield,
        );
        state.objects.insert(ObjectId(8), token);

        let unimplemented = |source: ObjectId| {
            ResolvedAbility::new(
                Effect::unimplemented("SomeEffect", "some fragment"),
                vec![],
                source,
                PlayerId(0),
            )
        };
        let mut events = Vec::new();

        // Oracle-id path: resolves and records the oracle id.
        resolve_effect(&mut state, &unimplemented(ObjectId(7)), &mut events).unwrap();
        assert!(state.unimplemented_oracle_ids.contains("oracle-abc-123"));

        // Dedup: a second resolution of the same source adds no new entry.
        resolve_effect(&mut state, &unimplemented(ObjectId(7)), &mut events).unwrap();
        assert_eq!(state.unimplemented_oracle_ids.len(), 1);

        // Name-fallback path: a token with no printed_ref records its name.
        resolve_effect(&mut state, &unimplemented(ObjectId(8)), &mut events).unwrap();
        assert!(state.unimplemented_oracle_ids.contains("Goblin Token"));
        assert_eq!(state.unimplemented_oracle_ids.len(), 2);
    }

    fn optional_gain_life(
        source_id: ObjectId,
        controller: PlayerId,
        amount: i32,
    ) -> ResolvedAbility {
        let mut ability = ResolvedAbility::new(
            Effect::GainLife {
                amount: QuantityExpr::Fixed { value: amount },
                player: TargetFilter::Controller,
            },
            vec![],
            source_id,
            controller,
        );
        ability.optional = true;
        ability
    }

    // Typed authority fixtures: these clauses deliberately do not claim printed-card reach.
    fn missing_referent_reasons() -> [ParentTargetMissingReason; 6] {
        [
            ParentTargetMissingReason::Dig,
            ParentTargetMissingReason::ChooseFromZone,
            ParentTargetMissingReason::RevealHandChoice,
            ParentTargetMissingReason::ExileTop,
            ParentTargetMissingReason::RevealUntil,
            ParentTargetMissingReason::SearchLibrary,
        ]
    }

    fn missing_referent_placement(source: ObjectId, targets: Vec<TargetRef>) -> ResolvedAbility {
        ResolvedAbility::new(
            Effect::PutAtLibraryPosition {
                target: TargetFilter::ParentTarget,
                count: QuantityExpr::Fixed { value: 1 },
                position: LibraryPosition::Top,
            },
            targets,
            source,
            PlayerId(0),
        )
    }

    #[test]
    fn missing_referent_handoff_preserves_own_targets_and_fresh_precedence() {
        let mut state = GameState::new_two_player(7);
        let mut parent = optional_gain_life(ObjectId(1), PlayerId(0), 1);
        parent.parent_target_missing_reason = Some(ParentTargetMissingReason::Dig);
        let mut child = missing_referent_placement(ObjectId(1), vec![]);
        state.last_parent_target_missing_reason = Some(ParentTargetMissingReason::ExileTop);
        apply_parent_chain_context(&mut child, &parent, None, &mut state);
        assert_eq!(
            child.parent_target_missing_reason,
            Some(ParentTargetMissingReason::ExileTop)
        );
        assert_eq!(state.last_parent_target_missing_reason, None);
        let mut unrelated = missing_referent_placement(ObjectId(2), vec![]);
        let fresh_parent = optional_gain_life(ObjectId(2), PlayerId(0), 1);
        apply_parent_chain_context(&mut unrelated, &fresh_parent, None, &mut state);
        assert_eq!(unrelated.parent_target_missing_reason, None);
        for reason in missing_referent_reasons() {
            parent.parent_target_missing_reason = Some(reason);
            let mut inherited = missing_referent_placement(ObjectId(1), vec![]);
            inherit_missing_parent_referent(&mut inherited, &parent);
            assert_eq!(inherited.parent_target_missing_reason, Some(reason));
            let mut own =
                missing_referent_placement(ObjectId(1), vec![TargetRef::Object(ObjectId(9))]);
            own.parent_target_missing_reason = Some(ParentTargetMissingReason::ExileTop);
            inherit_missing_parent_referent(&mut own, &parent);
            assert_eq!(own.targets, vec![TargetRef::Object(ObjectId(9))]);
            assert_eq!(
                own.parent_target_missing_reason,
                Some(ParentTargetMissingReason::ExileTop)
            );
        }
    }

    /// CR 608.2c + CR 609.3: Otherwise and declined branches retain an absent
    /// object, but their independently bound objects and following instructions survive.
    #[test]
    fn missing_referent_root_otherwise_and_public_optional_decline() {
        for reason in missing_referent_reasons()
            .into_iter()
            .map(Some)
            .chain([None])
        {
            for own_target in [false, true] {
                for optional in [false, true] {
                    let mut state = GameState::new_two_player(7);
                    let source = create_object(
                        &mut state,
                        CardId(1),
                        PlayerId(0),
                        "Authority source".into(),
                        Zone::Battlefield,
                    );
                    let own = create_object(
                        &mut state,
                        CardId(2),
                        PlayerId(0),
                        "Independent object".into(),
                        Zone::Exile,
                    );
                    let mut progress = optional_gain_life(source, PlayerId(0), 3);
                    progress.optional = false;
                    let branch = missing_referent_placement(
                        source,
                        if own_target {
                            vec![TargetRef::Object(own)]
                        } else {
                            vec![]
                        },
                    )
                    .sub_ability(progress);
                    let mut root = optional_gain_life(source, PlayerId(0), 2);
                    root.parent_target_missing_reason = reason;
                    root.else_ability = Some(Box::new(branch));
                    let mut events = Vec::new();
                    if optional {
                        resolve_ability_chain(&mut state, &root, &mut events, 1).unwrap();
                        assert!(matches!(
                            state.waiting_for,
                            WaitingFor::OptionalEffectChoice {
                                player: PlayerId(0),
                                ..
                            }
                        ));
                        assert_eq!(
                            state
                                .active_optional_effect_frame()
                                .unwrap()
                                .ability
                                .parent_target_missing_reason,
                            reason
                        );
                        events.extend(
                            crate::game::engine::apply_as_current(
                                &mut state,
                                GameAction::DecideOptionalEffect { accept: false },
                            )
                            .unwrap()
                            .events,
                        );
                    } else {
                        root.optional = false;
                        root.condition = Some(AbilityCondition::QuantityCheck {
                            lhs: QuantityExpr::Fixed { value: 0 },
                            comparator: Comparator::GT,
                            rhs: QuantityExpr::Fixed { value: 1 },
                        });
                        resolve_ability_chain(&mut state, &root, &mut events, 1).unwrap();
                    }
                    assert_eq!(
                        state.objects[&source].zone,
                        if reason.is_none() && !own_target {
                            Zone::Library
                        } else {
                            Zone::Battlefield
                        }
                    );
                    assert_eq!(
                        state.objects[&own].zone,
                        if own_target {
                            Zone::Library
                        } else {
                            Zone::Exile
                        }
                    );
                    assert_eq!(state.players[0].life, 23);
                    assert!(events.iter().any(|e| matches!(
                        e,
                        GameEvent::EffectResolved {
                            kind: EffectKind::PutAtLibraryPosition,
                            ..
                        }
                    )));
                    assert!(state.stack.is_empty());
                    assert!(matches!(state.waiting_for, WaitingFor::Priority { .. }));
                    assert!(state.active_optional_effect_frame().is_none());
                    assert!(state.active_ability_continuation().is_none());
                    assert!(state.resolution_stack.is_empty());
                }
            }
        }
        // CR 608.2d: Accepting the independent offer still performs it.
        let mut state = GameState::new_two_player(7);
        let mut offered = optional_gain_life(ObjectId(1), PlayerId(0), 2);
        offered.parent_target_missing_reason = Some(ParentTargetMissingReason::SearchLibrary);
        resolve_ability_chain(&mut state, &offered, &mut Vec::new(), 1).unwrap();
        assert_eq!(state.waiting_for.acting_player(), Some(PlayerId(0)));
        assert_eq!(
            state
                .active_optional_effect_frame()
                .unwrap()
                .ability
                .parent_target_missing_reason,
            offered.parent_target_missing_reason
        );
        crate::game::engine::apply_as_current(
            &mut state,
            GameAction::DecideOptionalEffect { accept: true },
        )
        .unwrap();
        assert_eq!(state.players[0].life, 22);
        assert!(matches!(state.waiting_for, WaitingFor::Priority { .. }));
        assert!(state.stack.is_empty() && state.resolution_stack.is_empty());
        // CR 608.2d: The impossible ParentTarget offer auto-declines through the same authority.
        let mut impossible = missing_referent_placement(ObjectId(1), vec![]);
        impossible.optional = true;
        impossible.parent_target_missing_reason = Some(ParentTargetMissingReason::SearchLibrary);
        let mut progress = optional_gain_life(ObjectId(1), PlayerId(0), 3);
        progress.optional = false;
        impossible.else_ability = Some(Box::new(progress));
        resolve_ability_chain(&mut state, &impossible, &mut Vec::new(), 1).unwrap();
        assert_eq!(state.players[0].life, 25);
        assert!(state.active_optional_effect_frame().is_none());
        assert!(matches!(state.waiting_for, WaitingFor::Priority { .. }));
        assert!(state.stack.is_empty() && state.resolution_stack.is_empty());
    }

    /// CR 603.12 + CR 608.2c: A nonmaterializing probe leaves the one-shot
    /// producer relay available to the actual handoff; a real trigger consumes it.
    #[test]
    fn missing_referent_reflexive_probe_restores_only_false_result() {
        let mut state = GameState::new_two_player(7);
        let parent = optional_gain_life(ObjectId(1), PlayerId(0), 1);
        let mut child = optional_gain_life(ObjectId(1), PlayerId(0), 2);
        child.optional = false;
        child.condition = Some(AbilityCondition::QuantityCheck {
            lhs: QuantityExpr::Fixed { value: 1 },
            comparator: Comparator::EQ,
            rhs: QuantityExpr::Fixed { value: 1 },
        });
        state.last_parent_target_missing_reason = Some(ParentTargetMissingReason::RevealUntil);
        let mut events = Vec::new();
        assert!(!try_materialize_reflexive_trigger(
            &mut state,
            &child,
            Some(&parent),
            None,
            &mut events,
            1
        )
        .unwrap());
        assert_eq!(
            state.last_parent_target_missing_reason,
            Some(ParentTargetMissingReason::RevealUntil)
        );
        assert!(state.stack.is_empty() && state.deferred_triggers.is_empty() && events.is_empty());
        apply_parent_chain_context(&mut child, &parent, None, &mut state);
        assert_eq!(
            child.parent_target_missing_reason,
            Some(ParentTargetMissingReason::RevealUntil)
        );
        assert_eq!(state.last_parent_target_missing_reason, None);
        child.set_unpinned_targets(vec![TargetRef::Object(ObjectId(9))]);
        state.last_parent_target_missing_reason = Some(ParentTargetMissingReason::ExileTop);
        assert!(!try_materialize_reflexive_trigger(
            &mut state,
            &child,
            Some(&parent),
            None,
            &mut events,
            1
        )
        .unwrap());
        assert_eq!(
            state.last_parent_target_missing_reason,
            Some(ParentTargetMissingReason::ExileTop)
        );
        child.set_unpinned_targets(vec![]);
        child.condition = Some(AbilityCondition::WhenYouDo);
        assert!(try_materialize_reflexive_trigger(
            &mut state,
            &child,
            Some(&parent),
            None,
            &mut events,
            1
        )
        .unwrap());
        assert_eq!(state.last_parent_target_missing_reason, None);
        assert_eq!(state.deferred_triggers.len(), 1);

        // Typed failure-path invariant: mandatory targeting errors after the
        // real parent handoff, and must retain that handoff's relay consumption.
        let mut state = GameState::new_two_player(7);
        let required_target = ResolvedAbility::new(
            Effect::Destroy {
                target: TargetFilter::Typed(TypedFilter::creature()),
                cant_regenerate: false,
            },
            vec![],
            ObjectId(1),
            PlayerId(0),
        );
        assert!(state.objects.is_empty());
        assert!(required_target.targets.is_empty());
        assert!(required_target.condition.is_none());
        assert!(!required_target.optional_targeting);
        assert!(parent.targets.is_empty());
        let target_error = crate::game::ability_utils::build_target_slots(&state, &required_target)
            .expect_err("a required creature slot has no legal target");
        state.last_parent_target_missing_reason = Some(ParentTargetMissingReason::ExileTop);
        let mut events = Vec::new();
        let error = try_materialize_reflexive_trigger(
            &mut state,
            &required_target,
            Some(&parent),
            None,
            &mut events,
            1,
        )
        .expect_err("the non-WhenYouDo target error is preserved");
        assert!(
            matches!(error, EffectError::InvalidParam(message) if message == target_error.to_string())
        );
        assert_eq!(state.last_parent_target_missing_reason, None);
        assert!(state.stack.is_empty() && state.deferred_triggers.is_empty() && events.is_empty());
        assert!(state.pending_trigger.is_none());
        assert!(state.resolution_stack.is_empty());
    }

    /// CR 608.2c: A second ordinary search has its own empty result even when
    /// following text is parked. This is an authority invariant, not printed reach.
    #[test]
    fn missing_referent_second_search_isolates_bound_result_through_postlude_and_drain() {
        for shape in 0..7 {
            let mut state = GameState::new_two_player(7);
            let source = create_object(
                &mut state,
                CardId(1),
                PlayerId(0),
                "Two producer source".into(),
                Zone::Battlefield,
            );
            let prior = create_object(
                &mut state,
                CardId(2),
                PlayerId(0),
                "Earlier result".into(),
                Zone::Library,
            );
            let mut reader = optional_gain_life(source, PlayerId(0), 1);
            reader.optional = false;
            reader.effect = Effect::GainLife {
                amount: QuantityExpr::Ref {
                    qty: QuantityRef::TrackedSetSize,
                },
                player: TargetFilter::Controller,
            };
            let first = ResolvedAbility::new(
                Effect::ExileTop {
                    count: QuantityExpr::Fixed { value: 1 },
                    player: TargetFilter::Controller,
                    position: LibraryPosition::Top,
                    face_down: false,
                    actor: LibraryInstructionActor::Controller,
                },
                vec![],
                source,
                PlayerId(0),
            )
            .sub_ability(reader.clone());
            let mut events = Vec::new();
            resolve_ability_chain(&mut state, &first, &mut events, 1).unwrap();
            let a = state
                .chain_tracked_set_id
                .expect("the first producer really published A");
            assert_eq!(state.tracked_object_sets[&a], vec![prior]);
            assert_eq!(state.objects[&prior].zone, Zone::Exile);
            assert_eq!(state.players[0].life, 21);
            let mut progress = optional_gain_life(source, PlayerId(0), 3);
            progress.optional = false;
            let consumer = reader.clone().sub_ability(progress.clone());
            let mut second = ResolvedAbility::new(
                Effect::SearchLibrary {
                    filter: TargetFilter::Any,
                    count: QuantityExpr::Fixed { value: 1 },
                    reveal: false,
                    target_player: None,
                    selection_constraint: SearchSelectionConstraint::None,
                    split: None,
                    source_zones: vec![Zone::Library],
                },
                vec![],
                source,
                PlayerId(0),
            );
            match shape {
                0 => second.sub_ability = Some(Box::new(consumer)),
                1 => append_to_pending_continuation(&mut state, Some(Box::new(consumer))),
                2 => {
                    let mut own_tail = optional_gain_life(source, PlayerId(0), 2);
                    own_tail.optional = false;
                    second.sub_ability = Some(Box::new(own_tail));
                    append_to_pending_continuation(&mut state, Some(Box::new(consumer)));
                }
                3 => second.sub_ability = Some(Box::new(progress.clone())),
                4 => {
                    let mut other = consumer;
                    other.source_id = ObjectId(99);
                    append_to_pending_continuation(&mut state, Some(Box::new(other)));
                }
                5 => {
                    let mut mode = progress.clone();
                    mode.modal_instruction_ordinal = Some(1);
                    second.sub_ability = Some(Box::new(mode));
                    append_to_pending_continuation(&mut state, Some(Box::new(consumer)));
                }
                6 => {
                    let mut mode = consumer;
                    mode.modal_instruction_ordinal = Some(1);
                    append_to_pending_continuation(&mut state, Some(Box::new(mode)));
                }
                _ => unreachable!(),
            }
            assert_eq!(second.source_id, source);
            assert_eq!(second.modal_instruction_ordinal, None);
            match shape {
                0 | 3 => {
                    assert!(state.active_ability_continuation().is_none());
                    let tail = second.sub_ability.as_deref().unwrap();
                    assert_eq!(tail.source_id, source);
                    assert_eq!(tail.modal_instruction_ordinal, None);
                    assert_eq!(
                        tail.effect,
                        if shape == 0 {
                            reader.effect.clone()
                        } else {
                            progress.effect.clone()
                        }
                    );
                    assert_eq!(chain_references_tracked_set(tail), shape == 0);
                }
                1 | 2 | 4 | 5 | 6 => {
                    let parked = state
                        .active_ability_continuation()
                        .expect("the accessor selects the intended parked frame");
                    assert_eq!(
                        parked.chain.source_id,
                        if shape == 4 { ObjectId(99) } else { source }
                    );
                    assert_eq!(
                        parked.chain.modal_instruction_ordinal,
                        if shape == 6 { Some(1) } else { None }
                    );
                    assert_eq!(parked.chain.effect, reader.effect);
                    assert_eq!(
                        parked.chain.sub_ability.as_deref().unwrap().effect,
                        progress.effect
                    );
                    assert_eq!(chain_references_tracked_set(&parked.chain), shape != 6);
                    match shape {
                        1 | 4 | 6 => assert!(second.sub_ability.is_none()),
                        2 | 5 => {
                            let tail = second.sub_ability.as_deref().unwrap();
                            assert_eq!(tail.source_id, source);
                            assert_eq!(
                                tail.modal_instruction_ordinal,
                                if shape == 5 { Some(1) } else { None }
                            );
                            assert!(!chain_references_tracked_set(tail));
                            assert_eq!(
                                tail.effect,
                                Effect::GainLife {
                                    amount: QuantityExpr::Fixed {
                                        value: if shape == 2 { 2 } else { 3 }
                                    },
                                    player: TargetFilter::Controller,
                                }
                            );
                        }
                        _ => unreachable!(),
                    }
                }
                _ => unreachable!(),
            }
            assert_eq!(
                state.chain_tracked_set_id,
                Some(a),
                "A must survive immediately before the depth-one second search"
            );
            assert_eq!(
                resolution_next_needs_tracked_set(&state, &second),
                shape < 3
            );
            // Inspect exclusions at the resolver boundary before any later mode reset.
            let mut boundary = state.clone();
            let mut boundary_events = Vec::new();
            search_library::resolve(&mut boundary, &second, &mut boundary_events).unwrap();
            assert_eq!(boundary.chain_tracked_set_id != Some(a), shape < 3);
            assert!(boundary_events.iter().any(|e| matches!(
                e,
                GameEvent::EffectResolved {
                    kind: EffectKind::SearchLibrary,
                    ..
                }
            )));
            resolve_ability_chain(&mut state, &second, &mut events, 1).unwrap();
            let b = state.chain_tracked_set_id.unwrap();
            if shape < 3 {
                assert_ne!(a, b);
                assert!(state.tracked_object_sets[&b].is_empty());
            }
            drain_pending_continuation(&mut state, &mut events);
            assert_eq!(state.tracked_object_sets[&a], vec![prior]);
            assert_eq!(state.objects[&prior].zone, Zone::Exile);
            if shape < 3 {
                assert_eq!(
                    state.players[0].life,
                    if shape == 2 { 26 } else { 24 },
                    "tracked-size gain is zero and independent progress completes"
                );
            }
            assert!(events.iter().any(|e| matches!(
                e,
                GameEvent::PlayerPerformedAction {
                    action: PlayerActionKind::SearchedLibrary,
                    ..
                }
            )));
            assert!(state.active_ability_continuation().is_none());
            assert!(matches!(state.waiting_for, WaitingFor::Priority { .. }));
            assert!(state.stack.is_empty() && state.resolution_stack.is_empty());
            assert!(state.active_library_searches.is_empty());
            assert!(state.active_search_decision_controls.is_empty());
            assert!(state.pending_search_found_batch.is_none());
        }
    }

    fn optional_stack_target_counter_move(
        source_id: ObjectId,
        targets: Vec<TargetRef>,
    ) -> ResolvedAbility {
        let mut ability = ResolvedAbility::new(
            Effect::MoveCounters {
                source: TargetFilter::Any,
                counter_type: Some(CounterType::Plus1Plus1),
                count: Some(QuantityExpr::Fixed { value: 1 }),
                mode: crate::types::ability::CounterTransferMode::Move,
                selection: crate::types::ability::CounterMoveSelection::StackTarget,
                target: TargetFilter::Any,
            },
            targets,
            source_id,
            PlayerId(0),
        );
        ability.optional = true;
        ability
    }

    /// CR 603.5 + CR 608.2d + CR 122.5: Tidus's two target slots may legally
    /// name the same creature, but that makes the optional counter move
    /// impossible. The resolver must therefore auto-decline it without a
    /// prompt while retaining the normal prompt for a distinct, counter-bearing
    /// sibling and routing the impossible branch through its printed else tail.
    #[test]
    fn optional_tidus_move_suppresses_only_impossible_prompt_and_runs_else() {
        let mut state = GameState::new_two_player(42);
        let tidus = create_object(
            &mut state,
            CardId(1),
            PlayerId(0),
            "Tidus, Yuna's Guardian".to_string(),
            Zone::Battlefield,
        );
        let sibling = create_object(
            &mut state,
            CardId(2),
            PlayerId(0),
            "Tidus's Ally".to_string(),
            Zone::Battlefield,
        );
        let start_life = state.players[0].life;

        let mut impossible = optional_stack_target_counter_move(
            tidus,
            vec![TargetRef::Object(tidus), TargetRef::Object(tidus)],
        );
        let mut else_ability =
            optional_gain_life(tidus, PlayerId(0), 1).condition(AbilityCondition::Not {
                condition: Box::new(AbilityCondition::EffectOutcome {
                    signal: EffectOutcomeSignal::OptionalEffectPerformed,
                }),
            });
        else_ability.optional = false;
        impossible.else_ability = Some(Box::new(else_ability));
        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &impossible, &mut events, 0)
            .expect("an impossible optional move auto-declines");
        assert!(
            !matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "same-object Tidus move must not offer an accept prompt"
        );
        assert_eq!(
            state.players[0].life,
            start_life + 1,
            "the auto-decline must preserve the explicit else continuation"
        );

        state
            .objects
            .get_mut(&tidus)
            .unwrap()
            .counters
            .insert(CounterType::Plus1Plus1, 1);
        let feasible = optional_stack_target_counter_move(
            tidus,
            vec![TargetRef::Object(tidus), TargetRef::Object(sibling)],
        );
        resolve_ability_chain(&mut state, &feasible, &mut events, 0)
            .expect("a feasible Tidus move resolves to the may gate");
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "a distinct destination with a counter source must remain offerable"
        );
    }

    /// CR 608.2b + CR 608.2d: target legality remains owned by the existing
    /// validation seam. Once a target changes controller or incarnation, the
    /// feasibility probe sees only the validated slots and suppresses a move
    /// that can no longer commit.
    #[test]
    fn optional_move_counter_feasibility_uses_validated_target_slots() {
        let mut state = GameState::new_two_player(42);
        let source = create_object(
            &mut state,
            CardId(1),
            PlayerId(0),
            "Counter Source".to_string(),
            Zone::Battlefield,
        );
        let destination = create_object(
            &mut state,
            CardId(2),
            PlayerId(0),
            "Counter Destination".to_string(),
            Zone::Battlefield,
        );
        for id in [source, destination] {
            state
                .objects
                .get_mut(&id)
                .unwrap()
                .card_types
                .core_types
                .push(CoreType::Creature);
        }
        state
            .objects
            .get_mut(&source)
            .unwrap()
            .counters
            .insert(CounterType::Plus1Plus1, 1);
        let controlled_creature = TargetFilter::Typed(TypedFilter {
            type_filters: vec![TypeFilter::Creature],
            controller: Some(ControllerRef::You),
            properties: vec![],
        });
        let mut ability = optional_stack_target_counter_move(
            source,
            vec![TargetRef::Object(source), TargetRef::Object(destination)],
        );
        let Effect::MoveCounters { target, .. } = &mut ability.effect else {
            unreachable!("test constructs MoveCounters");
        };
        *target = controlled_creature;
        ability.target_pins = vec![
            Some(ObjectIncarnationRef::from_object(&state.objects[&source])),
            Some(ObjectIncarnationRef::from_object(
                &state.objects[&destination],
            )),
        ];

        assert!(!optional_effect_is_infeasible(&state, &ability));
        state.objects.get_mut(&destination).unwrap().controller = PlayerId(1);
        let controller_changed =
            crate::game::ability_utils::validate_targets_in_chain(&state, &ability);
        assert_eq!(controller_changed.targets, vec![TargetRef::Object(source)]);
        assert!(optional_effect_is_infeasible(&state, &controller_changed));

        state.objects.get_mut(&destination).unwrap().controller = PlayerId(0);
        state.objects.get_mut(&destination).unwrap().incarnation += 1;
        let stale_incarnation =
            crate::game::ability_utils::validate_targets_in_chain(&state, &ability);
        assert_eq!(stale_incarnation.targets, vec![TargetRef::Object(source)]);
        assert!(optional_effect_is_infeasible(&state, &stale_incarnation));
    }

    /// CR 603.2 + CR 608.2d: feasibility must hydrate the same event-context
    /// target carrier as production resolution before resolving a quantity that
    /// reads that target. Without the explicit hydration in
    /// `optional_effect_is_infeasible`, the count reads zero from empty targets,
    /// auto-declines, and runs the else branch instead of reaching this prompt.
    #[test]
    fn optional_move_counter_feasibility_hydrates_target_dependent_quantity() {
        let mut state = GameState::new_two_player(42);
        let source = create_object(
            &mut state,
            CardId(1),
            PlayerId(0),
            "Counter Source".to_string(),
            Zone::Battlefield,
        );
        let destination = create_object(
            &mut state,
            CardId(2),
            PlayerId(0),
            "Triggered Destination".to_string(),
            Zone::Battlefield,
        );
        state
            .objects
            .get_mut(&source)
            .unwrap()
            .counters
            .insert(CounterType::Plus1Plus1, 2);
        state
            .objects
            .get_mut(&destination)
            .unwrap()
            .counters
            .insert(CounterType::Plus1Plus1, 1);
        state.current_trigger_event = Some(GameEvent::CounterAdded {
            object_id: destination,
            counter_type: CounterType::Plus1Plus1,
            count: 1,
            actor: PlayerId(0),
        });
        let mut ability = ResolvedAbility::new(
            Effect::MoveCounters {
                source: TargetFilter::SelfRef,
                counter_type: Some(CounterType::Plus1Plus1),
                count: Some(QuantityExpr::Ref {
                    qty: QuantityRef::CountersOn {
                        scope: ObjectScope::Target,
                        counter_type: Some(CounterType::Plus1Plus1),
                    },
                }),
                mode: crate::types::ability::CounterTransferMode::Move,
                selection: crate::types::ability::CounterMoveSelection::StackTarget,
                target: TargetFilter::TriggeringSource,
            },
            vec![],
            source,
            PlayerId(0),
        );
        ability.optional = true;
        let start_life = state.players[0].life;
        let mut else_ability = optional_gain_life(source, PlayerId(0), 1);
        else_ability.optional = false;
        else_ability.condition = Some(AbilityCondition::Not {
            condition: Box::new(AbilityCondition::effect_performed()),
        });
        ability.else_ability = Some(Box::new(else_ability));

        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &ability, &mut events, 0)
            .expect("hydrated target-dependent counter move reaches its may gate");
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "the hydrated event target makes the dynamic move offerable"
        );
        assert_eq!(
            state.players[0].life, start_life,
            "the else branch must not run while the hydrated move is offered"
        );
    }

    /// CR 608.2c + CR 608.2d + CR 122.5: an optional member-driven move must
    /// decide feasibility after each member is rebound. The first member is the
    /// source itself (an impossible same-object move), but the second is a
    /// distinct counter-bearing source/destination pair and remains offerable.
    #[test]
    fn optional_member_move_declines_only_impossible_member_and_reaches_later_prompt() {
        let mut state = GameState::new_two_player(42);
        let source = reflexive_test_creature(&mut state, PlayerId(0), "Counter Source");
        let destination = reflexive_test_creature(&mut state, PlayerId(0), "Later Destination");
        state
            .objects
            .get_mut(&source)
            .unwrap()
            .counters
            .insert(CounterType::Plus1Plus1, 1);

        let mut ability = ResolvedAbility::new(
            Effect::MoveCounters {
                source: TargetFilter::SelfRef,
                counter_type: Some(CounterType::Plus1Plus1),
                count: Some(QuantityExpr::Fixed { value: 1 }),
                mode: crate::types::ability::CounterTransferMode::Move,
                selection: crate::types::ability::CounterMoveSelection::StackTarget,
                target: TargetFilter::ParentTarget,
            },
            vec![TargetRef::Object(source)],
            source,
            PlayerId(0),
        );
        ability.optional = true;
        ability.repeat_for = Some(QuantityExpr::Ref {
            qty: QuantityRef::ObjectCount {
                filter: TargetFilter::Typed(TypedFilter::creature().controller(ControllerRef::You)),
            },
        });
        let start_life = state.players[0].life;
        let mut tail = optional_gain_life(source, PlayerId(0), 1);
        tail.optional = false;
        tail.sub_link = SubAbilityLink::SequentialSibling;
        ability.sub_ability = Some(Box::new(tail));

        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &ability, &mut events, 0)
            .expect("member-driven move resolves its first member");
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "the later distinct member must still receive its own may prompt"
        );
        assert_eq!(
            state.players[0].life,
            start_life + 1,
            "the impossible first member must retain its sequential continuation"
        );

        crate::game::engine_payment_choices::handle_optional_effect_choice(
            &mut state,
            true,
            &mut events,
        )
        .expect("accepting the later member resolves its move");
        assert!(
            !state.objects[&source]
                .counters
                .contains_key(&CounterType::Plus1Plus1),
            "the later feasible member must move the source counter"
        );
        assert_eq!(
            state.objects[&destination]
                .counters
                .get(&CounterType::Plus1Plus1)
                .copied(),
            Some(1),
            "the later distinct destination must receive the moved counter"
        );
        assert_eq!(
            state.players[0].life,
            start_life + 2,
            "the later accepted member must preserve its own sequential continuation"
        );
    }

    /// CR 614.6 + CR 608.2d + CR 122.5: counter replacement legality is not
    /// predicted by the structural optional probe. A destination that prevents
    /// counters still receives the production-shaped may prompt; replacement
    /// handling remains the counter resolver's responsibility after acceptance.
    #[test]
    fn optional_move_with_counter_prevention_remains_offerable() {
        let mut state = GameState::new_two_player(42);
        let source = reflexive_test_creature(&mut state, PlayerId(0), "Counter Source");
        let destination = reflexive_test_creature(&mut state, PlayerId(0), "No Counters");
        state
            .objects
            .get_mut(&source)
            .unwrap()
            .counters
            .insert(CounterType::Plus1Plus1, 1);
        let mut prevention = ReplacementDefinition::new(ReplacementEvent::AddCounter);
        prevention.valid_card = Some(TargetFilter::SelfRef);
        prevention.quantity_modification = Some(QuantityModification::Prevent);
        state
            .objects
            .get_mut(&destination)
            .unwrap()
            .replacement_definitions
            .push(prevention);

        let ability = optional_stack_target_counter_move(
            source,
            vec![TargetRef::Object(source), TargetRef::Object(destination)],
        );
        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &ability, &mut events, 0)
            .expect("replacement-sensitive counter move reaches its may gate");
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "counter-placement prevention must fail open instead of suppressing the may"
        );
        crate::game::engine_payment_choices::handle_optional_effect_choice(
            &mut state,
            true,
            &mut events,
        )
        .expect("accepting the replacement-sensitive move resolves through its pipeline");
        assert_eq!(
            state.objects[&source]
                .counters
                .get(&CounterType::Plus1Plus1)
                .copied(),
            Some(1),
            "the blocked move must leave the source counter in place"
        );
        assert!(
            !state.objects[&destination]
                .counters
                .contains_key(&CounterType::Plus1Plus1),
            "the replacement must prevent the destination counter placement"
        );
    }

    #[test]
    fn repeat_for_tracked_set_marks_ability_as_referencing_tracked_set() {
        // Issue #740 (Seasoned Pyromancer): "for each nonland card discarded this
        // way, create a token" carries its loop count as `repeat_for: TrackedSetSize`
        // on the ResolvedAbility, NOT inside Effect. The publish predicate must
        // detect it so the forced-discard path (no WaitingFor pause) still publishes
        // the tracked set; without this check the token loop sees size 0.
        let mut ability = optional_gain_life(ObjectId(1), PlayerId(0), 1);
        ability.optional = false;
        // Control: a plain GainLife with no `repeat_for` references no tracked set.
        assert!(
            !ability_or_branch_references_tracked_set(&ability),
            "baseline ability must not reference a tracked set"
        );
        // With a tracked-set loop count, the predicate must return true.
        ability.repeat_for = Some(QuantityExpr::Ref {
            qty: QuantityRef::TrackedSetSize,
        });
        assert!(
            ability_or_branch_references_tracked_set(&ability),
            "repeat_for: TrackedSetSize must mark the ability as referencing the tracked set"
        );
    }

    /// CR 608.2c + CR 608.2e: a producer at the end of a chain resumed under a
    /// parked same-source continuation reads that continuation as its following
    /// text; its own consumer, a mode boundary in its own chain, or a different
    /// source decide otherwise.
    #[test]
    fn resolution_next_needs_tracked_set_reads_a_parked_same_source_continuation() {
        let source = ObjectId(1);
        let draw = |count: QuantityExpr, src: ObjectId| {
            ResolvedAbility::new(
                Effect::Draw {
                    target: TargetFilter::Controller,
                    count,
                },
                vec![],
                src,
                PlayerId(0),
            )
        };
        let producer = |src| draw(QuantityExpr::Fixed { value: 1 }, src);
        let non_consumer = |src| draw(QuantityExpr::Fixed { value: 2 }, src);
        let consumer = |src| {
            draw(
                QuantityExpr::Ref {
                    qty: QuantityRef::TrackedSetSize,
                },
                src,
            )
        };
        let mut state = GameState::new_two_player(7);
        // Nothing parked and no consumer of its own.
        assert!(!resolution_next_needs_tracked_set(
            &state,
            &producer(source)
        ));
        // Its own consumer, nothing parked: the existing rule.
        assert!(resolution_next_needs_tracked_set(
            &state,
            &producer(source).sub_ability(consumer(source))
        ));
        // A parked same-source continuation that consumes nothing.
        append_to_pending_continuation(&mut state, Some(Box::new(non_consumer(source))));
        assert!(!resolution_next_needs_tracked_set(
            &state,
            &producer(source)
        ));
        state
            .take_active_ability_continuation()
            .expect("the parked non-consumer is the active frame");
        // A parked same-source consumer: the producer's chain end hands off.
        append_to_pending_continuation(&mut state, Some(Box::new(consumer(source))));
        assert!(resolution_next_needs_tracked_set(&state, &producer(source)));
        // A non-consuming own chain still ends in the parked consumer.
        assert!(resolution_next_needs_tracked_set(
            &state,
            &producer(source).sub_ability(non_consumer(source))
        ));
        // CR 700.2: a mode boundary inside the producer's own chain stops it.
        let mut next_mode = non_consumer(source);
        next_mode.modal_instruction_ordinal = Some(1);
        assert!(!resolution_next_needs_tracked_set(
            &state,
            &producer(source).sub_ability(next_mode)
        ));
        // CR 614.1: another object's chain resolving during the pause.
        assert!(!resolution_next_needs_tracked_set(
            &state,
            &producer(ObjectId(2))
        ));
    }

    /// CR 608.2c + CR 608.2d: only a Resolution-timed recipient choice whose own
    /// chain reads the set publishes on resume; a declared object, a head whose
    /// chain reads nothing, or a head that is not a counter instruction leaves
    /// the choice answer's publication in place.
    #[test]
    fn resolution_choice_head_publishes_on_resume_only_for_its_own_reader() {
        let reader = || {
            ResolvedAbility::new(
                Effect::Draw {
                    target: TargetFilter::Controller,
                    count: QuantityExpr::Ref {
                        qty: QuantityRef::TrackedSetSize,
                    },
                },
                vec![],
                ObjectId(1),
                PlayerId(0),
            )
        };
        let non_reader = || {
            ResolvedAbility::new(
                Effect::Draw {
                    target: TargetFilter::Controller,
                    count: QuantityExpr::Fixed { value: 1 },
                },
                vec![],
                ObjectId(1),
                PlayerId(0),
            )
        };
        let head = |effect: Effect, timing: TargetChoiceTiming| {
            let mut head = ResolvedAbility::new(effect, vec![], ObjectId(1), PlayerId(0));
            head.target_choice_timing = timing;
            head
        };
        let put_counter = || Effect::PutCounter {
            counter_type: CounterType::Plus1Plus1,
            count: QuantityExpr::Fixed { value: 2 },
            target: TargetFilter::Typed(TypedFilter::creature()),
        };
        let resolution = TargetChoiceTiming::Resolution;

        let recipient = head(put_counter(), resolution).sub_ability(reader());
        assert!(awaits_resolution_object_choice(&recipient));
        assert!(resolution_choice_head_publishes_on_resume(&recipient));
        // Its own chain reads nothing.
        assert!(!resolution_choice_head_publishes_on_resume(
            &head(put_counter(), resolution).sub_ability(non_reader())
        ));
        // The object was declared with the ability, not chosen while resolving.
        assert!(!resolution_choice_head_publishes_on_resume(
            &head(put_counter(), TargetChoiceTiming::Stack).sub_ability(reader())
        ));
        let mut bound = head(put_counter(), resolution).sub_ability(reader());
        bound.targets = vec![TargetRef::Object(ObjectId(5))];
        assert!(!resolution_choice_head_publishes_on_resume(&bound));
        // Not a counter instruction: the choice is the producer of the set.
        assert!(!resolution_choice_head_publishes_on_resume(
            &head(non_reader().effect, resolution).sub_ability(reader())
        ));
    }

    /// CR 601.2c + CR 608.2c: a node that declares a single optional object target
    /// ("up to one target creature", lowered with `optional_targeting` and no
    /// `multi_target`) is the nearest antecedent of its continuation's "that
    /// creature". When the player declines that target, the grant affects nothing.
    /// It must not reach an ancestor's tracked set.
    #[test]
    fn optional_single_target_node_is_the_antecedent_of_a_parent_target_grant() {
        let source = ObjectId(1);
        let grant = ResolvedAbility::new(
            Effect::GenericEffect {
                static_abilities: vec![StaticDefinition::continuous()
                    .affected(TargetFilter::ParentTarget)
                    .modifications(vec![ContinuousModification::AddKeyword {
                        keyword: Keyword::Haste,
                    }])],
                duration: Some(Duration::UntilEndOfTurn),
                target: None,
                end_cost: None,
            },
            vec![],
            source,
            PlayerId(0),
        );
        let mut pump = ResolvedAbility::new(
            Effect::Pump {
                power: PtValue::Fixed(1),
                toughness: PtValue::Fixed(1),
                target: TargetFilter::Typed(TypedFilter::creature()),
            },
            vec![],
            source,
            PlayerId(0),
        )
        .sub_ability(grant);
        // Control: with no declared target on the pump, the grant names the
        // chain's tracked set, so the instrument fires.
        assert!(
            chain_references_tracked_set(&pump),
            "a ParentTarget grant with no nearer antecedent consumes the tracked set"
        );
        pump.optional_targeting = true;
        assert!(
            !chain_references_tracked_set(&pump),
            "an optional single declared target is the grant's antecedent, so the \
             grant must not consume an ancestor's tracked set"
        );
        // A resolution-time "up to one" choice declares no target, so the grant
        // still names the chain's tracked set.
        pump.target_choice_timing = TargetChoiceTiming::Resolution;
        assert!(
            chain_references_tracked_set(&pump),
            "a resolution-time optional choice declares no target, so the grant \
             must still consume the tracked set"
        );
    }

    /// CR 608.2c — issue #6943 (Faerie Slumber Party). The Seasoned Pyromancer
    /// shape ONE LAYER UP: the tracked-set reference is nested inside the PLAYER
    /// filter of a `PlayerCount`, not in the quantity itself.
    ///
    /// This is the cheapest layer at which the de-registration regression is
    /// detectable, and its signature here is unique. `PlayerCount` is not
    /// intrinsically a tracked-set consumer, so the enclosing predicate must ask
    /// `player_filter_references_tracked_set` per filter. If it does not, the
    /// producing `BounceAll` never publishes, the set selection returns `None`,
    /// every player is rejected, and the count silently resolves to 0 — the card
    /// creates ZERO tokens instead of six, with nothing failing to compile.
    ///
    /// Revert discriminator: dropping the `QuantityRef::PlayerCount` arm from
    /// `quantity_expr_references_tracked_set` (i.e. restoring the `matches!`
    /// allowlist) makes the first assertion fail.
    #[test]
    fn repeat_for_player_count_over_tracked_set_possessors_references_tracked_set() {
        let mut ability = optional_gain_life(ObjectId(1), PlayerId(0), 1);
        ability.optional = false;
        assert!(
            !ability_or_branch_references_tracked_set(&ability),
            "baseline ability must not reference a tracked set"
        );

        // Faerie Slumber Party's repeat_for: "for each opponent who controlled a
        // creature returned this way".
        ability.repeat_for = Some(QuantityExpr::Ref {
            qty: QuantityRef::PlayerCount {
                filter: PlayerFilter::TrackedSetPossessor {
                    relation: crate::types::ability::PlayerRelation::Opponent,
                    possession: crate::types::ability::PossessionAxis::Controller,
                    filter: TargetFilter::Typed(TypedFilter {
                        type_filters: vec![TypeFilter::Creature],
                        ..Default::default()
                    }),
                    caused_by: None,
                },
            },
        });
        assert!(
            ability_or_branch_references_tracked_set(&ability),
            "repeat_for: PlayerCount over TrackedSetPossessor is a tracked-set CONSUMER — \
             without this the producer never publishes and the count resolves to 0"
        );

        // Paired negative: the arm must be FILTER-discriminating, not a blanket
        // `PlayerCount => true` that would make every existing player-count card
        // force a spurious tracked-set publication.
        ability.repeat_for = Some(QuantityExpr::Ref {
            qty: QuantityRef::PlayerCount {
                filter: PlayerFilter::Opponent,
            },
        });
        assert!(
            !ability_or_branch_references_tracked_set(&ability),
            "a plain PlayerCount{{Opponent}} reads no tracked set and must NOT force publication"
        );
    }

