    #[test]
    fn optional_triggering_source_zone_move_survives_optional_prompt() {
        let mut state = GameState::new_two_player(42);
        let source_id = create_object(
            &mut state,
            CardId(1),
            PlayerId(0),
            "Tergrid".to_string(),
            Zone::Battlefield,
        );
        let victim_id = create_object(
            &mut state,
            CardId(2),
            PlayerId(1),
            "Sacrificed Creature".to_string(),
            Zone::Graveyard,
        );
        state
            .objects
            .get_mut(&victim_id)
            .unwrap()
            .card_types
            .core_types
            .push(CoreType::Creature);
        state.current_trigger_event = Some(crate::types::events::GameEvent::PermanentSacrificed {
            object_id: victim_id,
            player_id: PlayerId(1),
        });

        let mut ability = ResolvedAbility::new(
            Effect::ChangeZone {
                origin: Some(Zone::Graveyard),
                destination: Zone::Battlefield,
                target: TargetFilter::TriggeringSource,
                owner_library: false,
                enter_transformed: false,
                enters_under: Some(ControllerRef::You),
                enter_tapped: crate::types::zones::EtbTapState::Unspecified,
                enters_attacking: false,
                up_to: false,
                enter_with_counters: vec![],
                conditional_enter_with_counters: vec![],
                face_down_profile: None,
                enters_modified_if: None,
            },
            vec![],
            source_id,
            PlayerId(0),
        );
        ability.optional = true;

        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &ability, &mut events, 0).unwrap();
        assert!(matches!(
            state.waiting_for,
            WaitingFor::OptionalEffectChoice { .. }
        ));
        state.current_trigger_event = None;

        let current = serde_json::to_value(ResolutionStateWire::from_game_state(state.clone()))
            .expect("real optional-effect prompt serializes through the current wire");
        assert_eq!(
            current["resolution_state_version"],
            RESOLUTION_STATE_WIRE_VERSION
        );
        assert!(current.get("pending_optional_effect").is_none());
        assert!(current.get("pending_optional_trigger_event").is_none());
        assert!(current
            .get("pending_optional_trigger_match_count")
            .is_none());
        state = serde_json::from_value::<ResolutionStateWire>(current)
            .expect("real optional-effect prompt round-trips through the current wire")
            .into_game_state();

        crate::game::engine::apply(
            &mut state,
            PlayerId(0),
            GameAction::DecideOptionalEffect { accept: true },
        )
        .unwrap();

        let victim = state.objects.get(&victim_id).unwrap();
        assert_eq!(victim.zone, Zone::Battlefield);
        assert_eq!(victim.controller, PlayerId(0));
        assert!(!state.players[1].graveyard.contains(&victim_id));
    }

