    /// CR 602.2a + CR 608.2c: Dragon Whelp's threshold — "If this ability has
    /// been activated four or more times this turn, sacrifice this creature at
    /// the beginning of the next end step."
    ///
    /// The reported bug (#8388) was that the sacrifice fired after three
    /// activations, because the clause parsed to no condition at all and the
    /// rider therefore ran unconditionally. The boundary is the whole assertion
    /// here: false at 3, true at 4.
    #[test]
    fn activation_tally_gates_on_the_printed_threshold() {
        let mut state = GameState::new_two_player(42);
        let source_id = ObjectId(1);
        let mut ability = ResolvedAbility::new(
            Effect::Draw {
                count: QuantityExpr::Fixed { value: 1 },
                target: TargetFilter::Controller,
            },
            vec![],
            source_id,
            PlayerId(0),
        );
        // Both activated-ability stack paths stamp this; see
        // `casting_costs::push_ability_entry`.
        ability.ability_index = Some(0);
        let condition = AbilityCondition::AbilityUseCountThisTurn {
            tally: AbilityUseTally::Activated,
            comparator: Comparator::GE,
            n: 4,
        };

        for activations in 0..4 {
            state
                .activated_abilities_this_turn
                .insert((source_id, 0), activations);
            assert!(
                !evaluate_condition(&condition, &state, &ability),
                "must not fire at {activations} activations — the printed \
                 threshold is four"
            );
        }

        state
            .activated_abilities_this_turn
            .insert((source_id, 0), 4);
        assert!(
            evaluate_condition(&condition, &state, &ability),
            "must fire once the fourth activation is recorded"
        );
        // "four OR MORE" — the gate stays satisfied past the boundary.
        state
            .activated_abilities_this_turn
            .insert((source_id, 0), 7);
        assert!(evaluate_condition(&condition, &state, &ability));
    }

    /// The two tallies read different ledgers, so neither may be satisfied by
    /// the other's counter. Without this, a single-ledger implementation would
    /// pass every threshold assertion above while making a countered activation
    /// (which never resolves) invisible to Dragon Whelp.
    #[test]
    fn activation_and_resolution_tallies_read_separate_ledgers() {
        let mut state = GameState::new_two_player(42);
        let source_id = ObjectId(1);
        let mut ability = ResolvedAbility::new(
            Effect::Draw {
                count: QuantityExpr::Fixed { value: 1 },
                target: TargetFilter::Controller,
            },
            vec![],
            source_id,
            PlayerId(0),
        );
        ability.ability_index = Some(0);

        // Four activations recorded, none of them resolved.
        state
            .activated_abilities_this_turn
            .insert((source_id, 0), 4);

        assert!(
            evaluate_condition(
                &AbilityCondition::AbilityUseCountThisTurn {
                    tally: AbilityUseTally::Activated,
                    comparator: Comparator::GE,
                    n: 4,
                },
                &state,
                &ability
            ),
            "activation tally must see the activation ledger"
        );
        assert!(
            !evaluate_condition(
                &AbilityCondition::nth_resolution_this_turn(4),
                &state,
                &ability
            ),
            "resolution tally must NOT be satisfied by activation counts"
        );
    }

    /// Abandon Attachments: "You may discard a card. If you do, draw two cards."
    /// Regression test for #81: after discarding, the IfYouDo draw-2 sub-ability
    /// must fire via the continuation chain. The bug was that context propagation
    /// or cost_payment_failed_flag was blocking the IfYouDo condition.
    #[test]
    fn optional_discard_if_you_do_draw_fires_after_choice() {
        let mut state = GameState::new_two_player(42);

        // Card in hand to discard
        let _hand_card = create_object(
            &mut state,
            CardId(10),
            PlayerId(0),
            "Fodder".to_string(),
            Zone::Hand,
        );

        // Cards in library to draw
        create_object(
            &mut state,
            CardId(11),
            PlayerId(0),
            "Draw A".to_string(),
            Zone::Library,
        );
        create_object(
            &mut state,
            CardId(12),
            PlayerId(0),
            "Draw B".to_string(),
            Zone::Library,
        );

        // Build Abandon Attachments: optional Discard 1 → sub: Draw 2 (IfYouDo)
        let sub = ResolvedAbility::new(
            Effect::Draw {
                count: QuantityExpr::Fixed { value: 2 },
                target: TargetFilter::Controller,
            },
            vec![],
            ObjectId(100),
            PlayerId(0),
        )
        .condition(AbilityCondition::effect_performed());

        let mut ability = ResolvedAbility::new(
            Effect::Discard {
                count: QuantityExpr::Fixed { value: 1 },
                target: TargetFilter::Controller,
                selection: crate::types::ability::CardSelectionMode::Chosen,
                unless_filter: None,
                filter: None,
            },
            vec![],
            ObjectId(100),
            PlayerId(0),
        )
        .sub_ability(sub);
        ability.optional = true;

        // Step 1: resolve_ability_chain → OptionalEffectChoice
        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &ability, &mut events, 0).unwrap();
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "Expected OptionalEffectChoice, got {:?}",
            state.waiting_for
        );

        // Step 2: Accept optional effect → forced discard (1 card in hand, count=1)
        // then IfYouDo sub-ability should fire drawing 2 cards.
        let waiting = crate::game::engine_payment_choices::handle_optional_effect_choice(
            &mut state,
            true,
            &mut events,
        )
        .unwrap();

        // Forced discard (hand_size == count) skips DiscardChoice, resolves inline.
        // After: discard 1 (-1), draw 2 (+2) = 2 cards in hand.
        let hand_after = state.players[0].hand.len();
        assert_eq!(
            hand_after,
            2,
            "After discarding 1 and drawing 2, hand should have 2 cards, got {}. \
             IfYouDo sub-ability likely did not fire. waiting_for={:?}, Events: {:?}",
            hand_after,
            waiting,
            events
                .iter()
                .filter(|e| matches!(
                    e,
                    GameEvent::EffectResolved { .. }
                        | GameEvent::Discarded { .. }
                        | GameEvent::CardsDrawn { .. }
                ))
                .collect::<Vec<_>>()
        );
    }

    /// CR 603.12 + CR 701.9a: If no card was discarded, a "when you do"
    /// reflexive trigger must not ask for its required target.
    #[test]
    fn optional_empty_hand_discard_does_not_create_reflexive_target_choice() {
        let mut state = GameState::new_two_player(42);
        let attacker = create_object(
            &mut state,
            CardId(10),
            PlayerId(0),
            "Attacking Creature".to_string(),
            Zone::Battlefield,
        );
        state
            .objects
            .get_mut(&attacker)
            .unwrap()
            .card_types
            .core_types
            .push(crate::types::card_type::CoreType::Creature);
        assert!(state.players[0].hand.is_empty());

        let reflexive = ResolvedAbility::new(
            Effect::PutCounter {
                counter_type: crate::types::counter::CounterType::Plus1Plus1,
                count: QuantityExpr::Fixed { value: 1 },
                target: TargetFilter::Typed(crate::types::ability::TypedFilter::creature()),
            },
            vec![],
            ObjectId(100),
            PlayerId(0),
        )
        .condition(AbilityCondition::WhenYouDo);
        let mut discard = ResolvedAbility::new(
            Effect::Discard {
                count: QuantityExpr::Fixed { value: 1 },
                target: TargetFilter::Controller,
                selection: crate::types::ability::CardSelectionMode::Chosen,
                unless_filter: None,
                filter: None,
            },
            vec![],
            ObjectId(100),
            PlayerId(0),
        )
        .sub_ability(reflexive);
        discard.optional = true;

        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &discard, &mut events, 0).unwrap();
        assert!(matches!(
            state.waiting_for,
            WaitingFor::OptionalEffectChoice { .. }
        ));
        let waiting = crate::game::engine_payment_choices::handle_optional_effect_choice(
            &mut state,
            true,
            &mut events,
        )
        .unwrap();

        assert!(
            !matches!(waiting, WaitingFor::TriggerTargetSelection { .. }),
            "an empty-hand discard must not create a reflexive target prompt"
        );
        assert!(state.objects[&attacker].counters.is_empty());
    }

    /// Abandon Attachments #81: interactive discard (player has 2+ cards) → IfYouDo draw 2.
    /// When the discard requires player interaction (DiscardChoice), the sub-ability
    /// must be stashed as a continuation and fire after the player selects a card.
    #[test]
    fn optional_discard_if_you_do_draw_fires_after_interactive_choice() {
        let mut state = GameState::new_two_player(42);

        // Two cards in hand so the discard is interactive (player must choose 1 of 2)
        let hand_card_a = create_object(
            &mut state,
            CardId(10),
            PlayerId(0),
            "Fodder A".to_string(),
            Zone::Hand,
        );
        let _hand_card_b = create_object(
            &mut state,
            CardId(11),
            PlayerId(0),
            "Fodder B".to_string(),
            Zone::Hand,
        );

        // Cards in library to draw
        create_object(
            &mut state,
            CardId(12),
            PlayerId(0),
            "Draw A".to_string(),
            Zone::Library,
        );
        create_object(
            &mut state,
            CardId(13),
            PlayerId(0),
            "Draw B".to_string(),
            Zone::Library,
        );

        // Build: optional Discard 1 → sub: Draw 2 (IfYouDo)
        let sub = ResolvedAbility::new(
            Effect::Draw {
                count: QuantityExpr::Fixed { value: 2 },
                target: TargetFilter::Controller,
            },
            vec![],
            ObjectId(100),
            PlayerId(0),
        )
        .condition(AbilityCondition::effect_performed());

        let mut ability = ResolvedAbility::new(
            Effect::Discard {
                count: QuantityExpr::Fixed { value: 1 },
                target: TargetFilter::Controller,
                selection: crate::types::ability::CardSelectionMode::Chosen,
                unless_filter: None,
                filter: None,
            },
            vec![],
            ObjectId(100),
            PlayerId(0),
        )
        .sub_ability(sub);
        ability.optional = true;

        // Step 1: resolve_ability_chain → OptionalEffectChoice
        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &ability, &mut events, 0).unwrap();
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "Expected OptionalEffectChoice, got {:?}",
            state.waiting_for
        );

        // Step 2: Accept optional effect → DiscardChoice (2 cards, must choose 1)
        let waiting = crate::game::engine_payment_choices::handle_optional_effect_choice(
            &mut state,
            true,
            &mut events,
        )
        .unwrap();
        assert!(
            matches!(waiting, WaitingFor::DiscardChoice { .. }),
            "Expected DiscardChoice after accepting optional with 2 cards in hand, got {:?}",
            waiting
        );

        // Verify the sub-ability was stashed as a pending continuation
        assert!(
            state.active_ability_continuation().is_some(),
            "IfYouDo sub-ability should be stashed as pending_continuation during DiscardChoice"
        );

        // Step 3: Select one card to discard
        let wf = state.waiting_for.clone();
        let _result = crate::game::engine_resolution_choices::handle_resolution_choice(
            &mut state,
            wf,
            crate::types::GameAction::SelectCards {
                cards: vec![hand_card_a],
            },
            &mut events,
        )
        .unwrap();

        // After: started with 2 in hand, discarded 1 (-1), drew 2 (+2) = 3 cards in hand.
        let hand_after = state.players[0].hand.len();
        assert_eq!(
            hand_after, 3,
            "After discarding 1 of 2 and drawing 2, hand should have 3 cards, got {}. \
             IfYouDo sub-ability likely did not fire.",
            hand_after,
        );
    }

    /// Issue #1972: Extort must prompt before draining, then pay {W/B}, drain each
    /// opponent, and gain life equal to the total life lost.
    #[test]
    fn issue_1972_extort_optional_accept_drains_all_opponents_and_gains() {
        let mut face = CardFace::default();
        face.keywords.push(Keyword::Extort);
        synthesize_extort(&mut face);
        let execute = face
            .triggers
            .iter()
            .find(|t| {
                matches!(t.mode, TriggerMode::SpellCast)
                    && matches!(t.execute.as_deref().map(|e| e.optional), Some(true))
            })
            .and_then(|t| t.execute.as_deref())
            .expect("synthesized extort trigger");

        let mut state = GameState::new(FormatConfig::standard(), 3, 42);
        let source_id = ObjectId(100);
        state.players[0].mana_pool.add(ManaUnit::new(
            ManaType::White,
            ObjectId(200),
            false,
            Vec::new(),
        ));
        let resolved = build_resolved_from_def(execute, source_id, PlayerId(0));
        let mut events = Vec::new();
        resolve_ability_chain(&mut state, &resolved, &mut events, 0).unwrap();
        assert!(
            matches!(state.waiting_for, WaitingFor::OptionalEffectChoice { .. }),
            "extort must prompt before draining, got {:?}",
            state.waiting_for
        );
        assert_eq!(
            (state.players[1].life, state.players[2].life),
            (20, 20),
            "opponents must not lose life before the may-pay decision"
        );

        crate::game::engine_payment_choices::handle_optional_effect_choice(
            &mut state,
            true,
            &mut events,
        )
        .unwrap();
        assert_eq!(state.players[0].life, 22);
        assert_eq!(state.players[1].life, 19);
        assert_eq!(state.players[2].life, 19);
        assert_eq!(state.players[0].mana_pool.total(), 0);
    }

